EXPECTED_EXECUTION='tatemono-collection-poc-9t6dt'
def main():
    base=['gcloud','--project',os.environ['GCP_PROJECT_ID'],'--quiet']
    def gc(args):
        p=subprocess.run(base+args,text=True,capture_output=True,timeout=1100)
        if p.returncode:
            print('BATCH_OPERATOR_ERROR='+json.dumps({'command':args[:3],'classes':sorted(set(re.findall(r'\\b(?:PERMISSION_DENIED|INVALID_ARGUMENT|NOT_FOUND|UNAUTHENTICATED|DEADLINE_EXCEEDED)\\b',p.stderr)))}),flush=True)
            raise SystemExit('batch_operator_command_failed')
        return p.stdout
    region=os.environ['GCP_REGION'];job=os.environ['GCP_JOB']
    meta=json.loads(gc(['run','jobs','describe',job,'--region',region,'--format=json(metadata.labels)']))
    if meta.get('metadata',{}).get('labels',{}).get('source-commit')!=EXPECTED_SOURCE:raise SystemExit('job_revision_changed')
    def active():
        return [x['metadata']['name'] for x in json.loads(gc(['run','jobs','executions','list','--job',job,'--region',region,'--format=json'])) if not x.get('status',{}).get('completionTime')]
    current=active()
    if current and current!=[EXPECTED_EXECUTION]:raise SystemExit('unexpected_active_execution')
    if current:
        gc(['run','jobs','executions','cancel',EXPECTED_EXECUTION,'--region',region])
        print('BATCH_OPERATOR_SAFE='+json.dumps({'cancel_requested':EXPECTED_EXECUTION}),flush=True)
        for attempt in range(30):
            if not active():break
            time.sleep(2)
        else:raise SystemExit('cancel_not_completed_refusing_second_execution')
    print('BATCH_OPERATOR_SAFE='+json.dumps({'active_collection':0,'inspection_only':True}),flush=True)
    start=datetime.now(timezone.utc).isoformat()
    gc(['run','jobs','execute',job,'--region',region,'--args=^~^-c~'+REMOTE,'--wait','--format=json'])
    query='resource.type="cloud_run_job" AND resource.labels.job_name="'+job+'" AND timestamp>="'+start+'"'
    raw=gc(['logging','read',query,'--limit=100','--order=asc','--format=json'])
    for item in json.loads(raw):
        line=item.get('textPayload') or (item.get('jsonPayload') or {}).get('message','')
        if isinstance(line,str) and line.startswith(('BATCH_DIAGNOSTIC_PRIVATE_REF=','BATCH_DIAGNOSTIC_ENCRYPTED=','BATCH_DIAGNOSTIC_SAFE=')):
            print(line,flush=True)
if __name__=='__main__':main()
